import heapq

CUSTO = {".": 1, "~": 3}   # custo para ENTRAR em cada terreno; "#" é parede
PASSOS = [(0, -1), (0, 1), (-1, 0), (1, 0)]   # cima, baixo, esquerda, direita


def vizinhas(grade, pos):
    x, y = pos
    livres = []
    for dx, dy in PASSOS:
        nx, ny = x + dx, y + dy
        if 0 <= ny < len(grade) and 0 <= nx < len(grade[ny]) and grade[ny][nx] in CUSTO:
            livres.append((nx, ny))
    return livres


def reconstruir(veio_de, fim):
    caminho = []
    atual = fim
    while atual is not None:
        caminho.append(atual)
        atual = veio_de[atual]
    caminho.reverse()
    return caminho


def heuristica(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def a_estrela(grade, inicio, fim):
    custo = {inicio: 0}
    veio_de = {inicio: None}
    fila = [(heuristica(inicio, fim), inicio)]
    while fila:
        _, atual = heapq.heappop(fila)
        if atual == fim:
            return custo[fim], reconstruir(veio_de, fim)
        for vizinha in vizinhas(grade, atual):
            x, y = vizinha
            novo = custo[atual] + CUSTO[grade[y][x]]
            if vizinha not in custo or novo < custo[vizinha]:
                custo[vizinha] = novo
                veio_de[vizinha] = atual
                heapq.heappush(fila, (novo + heuristica(vizinha, fim), vizinha))
    return None


