# Mini roguelike: pegue todas as moedas ($) sem ser pego pelos inimigos (E).
# Posições são tuplas (x, y): x é a coluna e y é a linha (cresce para BAIXO).
from collections import deque

DIRECOES = {"cima": (0, -1), "baixo": (0, 1), "esquerda": (-1, 0), "direita": (1, 0)}
TECLAS = {"w": "cima", "a": "esquerda", "s": "baixo", "d": "direita"}
VIDA_INICIAL = 3
VISAO = 6   # um inimigo só persegue se o caminho até você tiver no máximo 6 passos


def ler_mapa(texto):
    linhas = texto.strip().splitlines()
    mapa = {"largura": len(linhas[0]), "altura": len(linhas), "paredes": set(),
            "moedas": set(), "inicio": None, "inimigos": []}
    for y, linha in enumerate(linhas):
        for x, casa in enumerate(linha):
            if casa == "#":
                mapa["paredes"].add((x, y))
            elif casa == "$":
                mapa["moedas"].add((x, y))
            elif casa == "@":
                mapa["inicio"] = (x, y)
            elif casa == "E":
                mapa["inimigos"].append((x, y))
    return mapa


def dentro(pos, mapa):
    x, y = pos
    return 0 <= x < mapa["largura"] and 0 <= y < mapa["altura"]


def vizinhos(pos, mapa):
    x, y = pos
    livres = []
    for dx, dy in DIRECOES.values():   # cima, baixo, esquerda, direita
        vizinho = (x + dx, y + dy)
        if dentro(vizinho, mapa) and vizinho not in mapa["paredes"]:
            livres.append(vizinho)
    return livres


def mover(pos, direcao, mapa):
    if direcao not in DIRECOES:
        return pos
    dx, dy = DIRECOES[direcao]
    destino = (pos[0] + dx, pos[1] + dy)
    if not dentro(destino, mapa) or destino in mapa["paredes"]:
        return pos
    return destino


def caminho(mapa, inicio, fim):
    veio_de = {inicio: None}
    fila = deque([inicio])
    while fila:
        atual = fila.popleft()
        if atual == fim:
            rota = []
            while atual is not None:
                rota.append(atual)
                atual = veio_de[atual]
            rota.reverse()
            return rota
        for vizinho in vizinhos(atual, mapa):
            if vizinho not in veio_de:
                veio_de[vizinho] = atual
                fila.append(vizinho)
    return None


class Eventos:
    def __init__(self):
        self.ouvintes = {}

    def assinar(self, nome, funcao):
        if nome not in self.ouvintes:
            self.ouvintes[nome] = []
        self.ouvintes[nome].append(funcao)

    def emitir(self, nome, **dados):
        for funcao in self.ouvintes.get(nome, []):
            funcao(**dados)


def novo_jogo(texto):
    mapa = ler_mapa(texto)
    return {
        "mapa": mapa,                          # paredes, largura, altura...
        "jogador": mapa["inicio"],             # posição (x, y) do jogador
        "inimigos": list(mapa["inimigos"]),    # posições dos inimigos, em ordem
        "restantes": set(mapa["moedas"]),      # moedas que ainda estão no mapa
        "vida": VIDA_INICIAL,
        "moedas": 0,                           # moedas já pegas
        "turnos": 0,
        "situacao": "jogando",                 # "jogando", "venceu" ou "perdeu"
    }


# ---------------------------------------------------------------------------
# Escreva daqui para baixo.


def desenhar(estado):
    mapa = estado["mapa"]
    linhas = []
    for y in range(mapa["altura"]):
        linha = ""
        for x in range(mapa["largura"]):
            pos = (x, y)
            if pos in mapa["paredes"]:
                linha += "#"
            elif pos == estado["jogador"]:
                linha += "@"
            elif pos in estado["inimigos"]:
                linha += "E"
            elif pos in estado["restantes"]:
                linha += "$"
            else:
                linha += "."
        linhas.append(linha)
    return "\n".join(linhas)


def distancia(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def mover_jogador(estado, comando, eventos):
    if comando not in TECLAS:
        return
    destino = mover(estado["jogador"], TECLAS[comando], estado["mapa"])
    if destino in estado["inimigos"]:
        return
    estado["jogador"] = destino
    if destino in estado["restantes"]:
        estado["restantes"].remove(destino)
        estado["moedas"] += 1
        eventos.emitir("moeda", pos=destino)


def agir_inimigos(estado, eventos):
    for i, inimigo in enumerate(estado["inimigos"]):
        if distancia(inimigo, estado["jogador"]) == 1:
            estado["vida"] -= 1
            eventos.emitir("dano", vida=estado["vida"])
            if estado["vida"] == 0:
                estado["situacao"] = "perdeu"
                eventos.emitir("fim", situacao="perdeu")
                return
        else:
            rota = caminho(estado["mapa"], inimigo, estado["jogador"])
            if rota is not None and len(rota) - 1 <= VISAO and rota[1] not in estado["inimigos"]:
                estado["inimigos"][i] = rota[1]


def turno(estado, comando, eventos):
    if estado["situacao"] != "jogando":
        return estado
    estado["turnos"] += 1
    mover_jogador(estado, comando, eventos)
    if not estado["restantes"]:
        estado["situacao"] = "venceu"
        eventos.emitir("fim", situacao="venceu")
        return estado
    agir_inimigos(estado, eventos)
    return estado


def jogar(mapa_texto, comandos, eventos=None):
    if eventos is None:
        eventos = Eventos()
    estado = novo_jogo(mapa_texto)
    for comando in comandos:
        estado = turno(estado, comando, eventos)
    return estado


