def main():
    eventos = Eventos()
    eventos.assinar("moeda", lambda **dados: print("Você pegou uma moeda!"))
    eventos.assinar("dano", lambda **dados: print("Um inimigo te acertou! Vida:", dados["vida"]))
    estado = novo_jogo(MAPA)
    while estado["situacao"] == "jogando":
        print(desenhar(estado))
        print(f"Vida: {estado['vida']}   Moedas: {estado['moedas']}   Turno: {estado['turnos']}")
        comando = input("w/a/s/d para andar, Enter para esperar, q para sair: ").strip().lower()
        if comando == "q":
            break
        estado = turno(estado, comando, eventos)
        print()
    print(desenhar(estado))
    if estado["situacao"] == "venceu":
        print("Você pegou todas as moedas. Vitória!")
    elif estado["situacao"] == "perdeu":
        print("Os inimigos te pegaram. Fim de jogo.")
    else:
        print("Até a próxima!")


